def Optional_Settings(server_id=None, environment=None, base_url=None, provider=None, account_label=None, secret=None, create_identity=None, create_session=None, session_id=None, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0393000" if __import__("os").path.isdir("./environment_mix/0393000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---------- validation ----------
    try:
        if server_id is not None:
            if not isinstance(server_id, str):
                return _err("VALIDATION_ERROR", "server_id must be a string")
            if not re.match(r"^mcp_srv_[0-9A-HJKMNP-TV-Z]{18,}$", server_id):
                return _err("VALIDATION_ERROR", "server_id has invalid format")
        if session_id is not None:
            if not isinstance(session_id, str):
                return _err("VALIDATION_ERROR", "session_id must be a string")
            if not re.match(r"^mcp_sess_[0-9A-HJKMNP-TV-Z]{18,}$", session_id):
                return _err("VALIDATION_ERROR", "session_id has invalid format")
        if environment is not None:
            if not isinstance(environment, str):
                return _err("VALIDATION_ERROR", "environment must be a string")
            if environment not in ["local", "dev", "staging", "prod"]:
                return _err("VALIDATION_ERROR", "environment must be one of: local, dev, staging, prod")
        if base_url is not None:
            if not isinstance(base_url, str):
                return _err("VALIDATION_ERROR", "base_url must be a string")
            if base_url.strip() == "":
                return _err("VALIDATION_ERROR", "base_url must not be empty")
        if provider is not None:
            if not isinstance(provider, str):
                return _err("VALIDATION_ERROR", "provider must be a string")
            if provider not in ["supabase_pat", "oauth", "service_role_key", "anon_key"]:
                return _err("VALIDATION_ERROR", "provider must be one of: supabase_pat, oauth, service_role_key, anon_key")
        if account_label is not None and not isinstance(account_label, str):
            return _err("VALIDATION_ERROR", "account_label must be a string")
        if secret is not None and not isinstance(secret, str):
            return _err("VALIDATION_ERROR", "secret must be a string")
        if create_identity is not None and not isinstance(create_identity, bool):
            return _err("VALIDATION_ERROR", "create_identity must be a boolean")
        if create_session is not None and not isinstance(create_session, bool):
            return _err("VALIDATION_ERROR", "create_session must be a boolean")

        # If creating identity/session, must have provider+secret
        if create_identity is True or create_session is True:
            if provider is None:
                return _err("VALIDATION_ERROR", "provider is required when create_identity or create_session is true")
            if secret is None or secret.strip() == "":
                return _err("VALIDATION_ERROR", "secret is required when create_identity or create_session is true")
    except Exception as e:
        return _err("VALIDATION_ERROR", "Invalid parameters", detail=str(e))

    # ---------- load store ----------
    servers = _load("mcp_servers.json")
    identities = _load("auth_identities.json")
    sessions = _load("auth_sessions.json")
    audits = _load("audit_events.json")

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # time-based plus randomness
        raw = (datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + os.urandom(10).hex()).encode("utf-8")
        h = hashlib.sha256(raw).digest()
        n = 0
        for b in h[:16]:
            n = (n << 8) | b
        chars = []
        for _ in range(26):
            n, r = divmod(n, 32)
            chars.append(alphabet[r])
        return prefix + "".join(reversed(chars))

    def _audit(server_id_val, identity_id_val, session_id_val, event_type, success, metadata=None):
        ae = {
            "id": _b32_id("mcp_aud_"),
            "server_id": server_id_val,
            "identity_id": identity_id_val,
            "session_id": session_id_val,
            "event_type": event_type,
            "success": bool(success),
            "ip_address": None,
            "user_agent": None,
            "metadata": metadata if isinstance(metadata, dict) else (None if metadata is None else {"detail": str(metadata)}),
            "created_at": now,
            "updated_at": now
        }
        audits.append(ae)

    def _fingerprint(s):
        # redacted fingerprint only (no plaintext)
        h = hashlib.sha256(s.encode("utf-8")).hexdigest()
        return {"sha256_8": h[:8], "last4": s[-4:] if len(s) >= 4 else s}

    # ---------- resolve server context (ambient) ----------
    resolved_server = None
    if server_id is not None:
        resolved_server = next((r for r in servers if r.get("id") == server_id), None)
        if resolved_server is None:
            # log attempt with any server? cannot, server_id missing reference; use best-effort: no audit row possible without server_id FK
            return _err("NOT_FOUND", "Server not found", server_id=server_id)
    else:
        # derive default: most recently seen active/disabled server (not deleted), else any server
        def _dt(x):
            v = x.get("last_seen_at") or x.get("updated_at") or x.get("created_at")
            return v or ""
        candidates = [s for s in servers if s.get("status") in ("active", "disabled")]
        if environment is not None:
            candidates = [s for s in candidates if s.get("environment") == environment]
        if base_url is not None:
            candidates = [s for s in candidates if s.get("base_url") == base_url]
        if not candidates:
            candidates = [s for s in servers if s.get("status") != "deleted"]
            if environment is not None:
                candidates = [s for s in candidates if s.get("environment") == environment]
            if base_url is not None:
                candidates = [s for s in candidates if s.get("base_url") == base_url]
        if not candidates:
            candidates = [s for s in servers]
            if environment is not None:
                candidates = [s for s in candidates if s.get("environment") == environment]
            if base_url is not None:
                candidates = [s for s in candidates if s.get("base_url") == base_url]
        if candidates:
            candidates.sort(key=_dt, reverse=True)
            resolved_server = candidates[0]

    if resolved_server is None:
        # no server in store to act upon
        return _err("UNAUTHORIZED", "No stored server profile available to resolve context")

    # validate optional filters against resolved server if provided
    if environment is not None and resolved_server.get("environment") != environment:
        return _err("CONFLICT", "Requested environment does not match resolved server", resolved_environment=resolved_server.get("environment"))
    if base_url is not None and resolved_server.get("base_url") != base_url:
        return _err("CONFLICT", "Requested base_url does not match resolved server", resolved_base_url=resolved_server.get("base_url"))

    # deleted server cannot create identities/sessions
    if resolved_server.get("status") == "deleted" and (create_identity is True or create_session is True or secret is not None or provider is not None):
        _audit(resolved_server["id"], None, None, "auth.signin.failed", False, {"reason": "server_deleted"})
        _save("audit_events.json", audits)
        return _err("INVALID_TRANSITION", "Cannot create identities or sessions for a deleted server", server_id=resolved_server["id"])

    # ---------- session expiration enforcement on read/use attempts ----------
    changed_sessions = False
    try:
        for s in sessions:
            if s.get("server_id") != resolved_server.get("id"):
                continue
            if s.get("status") == "active" and s.get("expires_at"):
                # expires_at stored as ISO Z
                try:
                    exp = s["expires_at"]
                    exp_dt = datetime.datetime.fromisoformat(exp.replace("Z", "+00:00"))
                    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
                    if exp_dt <= now_dt:
                        s["status"] = "expired"
                        s["updated_at"] = now
                        changed_sessions = True
                except Exception:
                    # if bad timestamp, mark error
                    s["status"] = "error"
                    s["last_error"] = "Invalid expires_at timestamp"
                    s["updated_at"] = now
                    changed_sessions = True
    except Exception as e:
        return _err("VALIDATION_ERROR", "Failed to process session expiration", detail=str(e))

    # ---------- resolve or create session/identity ----------
    resolved_identity = None
    resolved_session = None

    # If an existing session_id is provided, use it (must match server)
    if session_id is not None:
        resolved_session = next((s for s in sessions if s.get("id") == session_id), None)
        if resolved_session is None:
            _audit(resolved_server["id"], None, None, "auth.signin.failed", False, {"reason": "session_not_found", "session_id": session_id})
            _save("audit_events.json", audits)
            if changed_sessions:
                _save("auth_sessions.json", sessions)
            return _err("NOT_FOUND", "Session not found", session_id=session_id)
        if resolved_session.get("server_id") != resolved_server.get("id"):
            _audit(resolved_server["id"], resolved_session.get("identity_id"), resolved_session.get("id"), "auth.signin.failed", False, {"reason": "session_server_mismatch"})
            _save("audit_events.json", audits)
            if changed_sessions:
                _save("auth_sessions.json", sessions)
            return _err("CONFLICT", "Session does not belong to resolved server", server_id=resolved_server["id"], session_server_id=resolved_session.get("server_id"))
        resolved_identity = next((i for i in identities if i.get("id") == resolved_session.get("identity_id")), None)

    # If requested, create/update identity and/or create session using provided creds
    if create_identity is True or create_session is True:
        _audit(resolved_server["id"], None, None, "auth.signin.started", True, {"provider": provider, "account_label": account_label, "secret_fp": _fingerprint(secret)})
        # identity upsert
        if create_identity is True:
            existing = None
            for i in identities:
                if i.get("server_id") == resolved_server["id"] and i.get("provider") == provider and (i.get("account_label") or None) == (account_label or None):
                    existing = i
                    break
            if existing is not None:
                if existing.get("status") in ("revoked", "deleted"):
                    _audit(resolved_server["id"], existing.get("id"), None, "auth.signin.failed", False, {"reason": "identity_revoked_or_deleted"})
                    _save("audit_events.json", audits)
                    if changed_sessions:
                        _save("auth_sessions.json", sessions)
                    return _err("INVALID_TRANSITION", "Identity is revoked/deleted and cannot be updated for use", identity_id=existing.get("id"))
                existing["secret_ciphertext"] = "enc:" + hashlib.sha256(secret.encode("utf-8")).hexdigest()
                existing["secret_kid"] = "local-kid-1"
                existing["updated_at"] = now
                resolved_identity = existing
            else:
                # ensure server not deleted handled above
                new_id = {
                    "id": _b32_id("mcp_idn_"),
                    "server_id": resolved_server["id"],
                    "provider": provider,
                    "account_label": account_label if account_label is not None else None,
                    "secret_ciphertext": "enc:" + hashlib.sha256(secret.encode("utf-8")).hexdigest(),
                    "secret_kid": "local-kid-1",
                    "status": "active",
                    "last_used_at": None,
                    "created_at": now,
                    "updated_at": now
                }
                # enforce unique(server_id, provider, account_label)
                if any(i.get("server_id") == new_id["server_id"] and i.get("provider") == new_id["provider"] and (i.get("account_label") or None) == (new_id["account_label"] or None) for i in identities):
                    _audit(resolved_server["id"], None, None, "auth.signin.failed", False, {"reason": "identity_unique_conflict"})
                    _save("audit_events.json", audits)
                    if changed_sessions:
                        _save("auth_sessions.json", sessions)
                    return _err("CONFLICT", "Identity already exists for (server_id, provider, account_label)")
                identities.append(new_id)
                resolved_identity = new_id

        # if create_session, need an identity (either just created/updated, or find a suitable one)
        if create_session is True:
            if resolved_identity is None:
                # find active identity for server/provider/account_label
                cand = [i for i in identities if i.get("server_id") == resolved_server["id"] and i.get("provider") == provider and (i.get("account_label") or None) == (account_label or None)]
                cand = [i for i in cand if i.get("status") == "active"]
                if not cand:
                    _audit(resolved_server["id"], None, None, "auth.signin.failed", False, {"reason": "no_active_identity"})
                    _save("audit_events.json", audits)
                    if changed_sessions:
                        _save("auth_sessions.json", sessions)
                    return _err("UNAUTHORIZED", "No active identity available for requested provider/account_label on this server")
                resolved_identity = cand[0]

            if resolved_identity.get("status") in ("revoked", "deleted"):
                _audit(resolved_server["id"], resolved_identity.get("id"), None, "auth.signin.failed", False, {"reason": "identity_revoked_or_deleted"})
                _save("audit_events.json", audits)
                if changed_sessions:
                    _save("auth_sessions.json", sessions)
                return _err("INVALID_TRANSITION", "Identity cannot be used to create sessions", identity_id=resolved_identity.get("id"))

            # Enforce one active session per (server_id, identity_id): revoke previous active
            for s in sessions:
                if s.get("server_id") == resolved_server["id"] and s.get("identity_id") == resolved_identity["id"] and s.get("status") == "active":
                    s["status"] = "revoked"
                    s["updated_at"] = now
                    changed_sessions = True
                    _audit(resolved_server["id"], resolved_identity.get("id"), s.get("id"), "auth.session.revoked", True, {"reason": "superseded"})

            # Create a new session row. For static-key providers, tokens may be null.
            new_sess = {
                "id": _b32_id("mcp_sess_"),
                "server_id": resolved_server["id"],
                "identity_id": resolved_identity["id"],
                "access_token_ciphertext": None,
                "refresh_token_ciphertext": None,
                "expires_at": None,
                "status": "active",
                "last_error": None,
                "created_at": now,
                "updated_at": now
            }
            if provider in ("oauth", "supabase_pat"):
                # simulate minted access token expiring in 1 hour
                exp_dt = datetime.datetime.utcnow().replace(microsecond=0) + datetime.timedelta(hours=1)
                new_sess["access_token_ciphertext"] = "enc:" + hashlib.sha256((secret + "|access").encode("utf-8")).hexdigest()
                new_sess["refresh_token_ciphertext"] = "enc:" + hashlib.sha256((secret + "|refresh").encode("utf-8")).hexdigest()
                new_sess["expires_at"] = exp_dt.isoformat() + "Z"
            sessions.append(new_sess)
            resolved_session = new_sess

            # update identity last_used_at
            resolved_identity["last_used_at"] = now
            resolved_identity["updated_at"] = now

            # server last_seen_at
            resolved_server["last_seen_at"] = now
            resolved_server["updated_at"] = now

            _audit(resolved_server["id"], resolved_identity.get("id"), resolved_session.get("id"), "auth.signin.succeeded", True, {"provider": provider, "account_label": account_label})
        else:
            # if only identity creation/update
            resolved_identity["last_used_at"] = now
            resolved_identity["updated_at"] = now
            resolved_server["last_seen_at"] = now
            resolved_server["updated_at"] = now
            _audit(resolved_server["id"], resolved_identity.get("id"), None, "auth.signin.succeeded", True, {"provider": provider, "account_label": account_label})

    # If no explicit create_session and no session_id provided: resolve a default session (most recent active) if any
    if resolved_session is None:
        cand = [s for s in sessions if s.get("server_id") == resolved_server["id"]]
        # enforce expiration update might have changed statuses
        def _key(s):
            return s.get("updated_at") or s.get("created_at") or ""
        cand.sort(key=_key, reverse=True)
        # prefer active
        active = [s for s in cand if s.get("status") == "active"]
        resolved_session = active[0] if active else (cand[0] if cand else None)
        if resolved_session is not None and resolved_identity is None:
            resolved_identity = next((i for i in identities if i.get("id") == resolved_session.get("identity_id")), None)
        # update last_seen when merely used
        resolved_server["last_seen_at"] = now
        resolved_server["updated_at"] = now

    # ---------- persist changes ----------
    _save("audit_events.json", audits)
    if create_identity is True or create_session is True:
        _save("auth_identities.json", identities)
        _save("auth_sessions.json", sessions)
        _save("mcp_servers.json", servers)
    else:
        if changed_sessions:
            _save("auth_sessions.json", sessions)
        _save("mcp_servers.json", servers)

    latency_ms = int((time.time() - t0) * 1000)

    # response envelope
    out = {
        "server": {
            "id": resolved_server.get("id"),
            "name": resolved_server.get("name"),
            "base_url": resolved_server.get("base_url"),
            "environment": resolved_server.get("environment"),
            "status": resolved_server.get("status"),
            "last_seen_at": resolved_server.get("last_seen_at"),
            "created_at": resolved_server.get("created_at"),
            "updated_at": resolved_server.get("updated_at")
        },
        "identity": None,
        "session": None,
        "meta": {"latency_ms": latency_ms}
    }
    if resolved_identity is not None:
        out["identity"] = {
            "id": resolved_identity.get("id"),
            "server_id": resolved_identity.get("server_id"),
            "provider": resolved_identity.get("provider"),
            "account_label": resolved_identity.get("account_label"),
            "status": resolved_identity.get("status"),
            "last_used_at": resolved_identity.get("last_used_at"),
            "created_at": resolved_identity.get("created_at"),
            "updated_at": resolved_identity.get("updated_at")
        }
    if resolved_session is not None:
        out["session"] = {
            "id": resolved_session.get("id"),
            "server_id": resolved_session.get("server_id"),
            "identity_id": resolved_session.get("identity_id"),
            "expires_at": resolved_session.get("expires_at"),
            "status": resolved_session.get("status"),
            "last_error": resolved_session.get("last_error"),
            "created_at": resolved_session.get("created_at"),
            "updated_at": resolved_session.get("updated_at")
        }
    return out

def List_MCP_Servers(environment=None, status=None, q=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0393000" if __import__("os").path.isdir("./environment_mix/0393000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # validate
    if environment is not None:
        if not isinstance(environment, str):
            return _err("VALIDATION_ERROR", "environment must be a string")
        if environment not in ["local", "dev", "staging", "prod"]:
            return _err("VALIDATION_ERROR", "Invalid environment")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ["active", "disabled", "deleted"]:
            return _err("VALIDATION_ERROR", "Invalid status")
    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "q must be a string")
    if limit is None:
        limit = 25
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 100:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    servers = _load("mcp_servers.json")
    audits = _load("audit_events.json")

    # decode cursor
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    rows = [s for s in servers]
    if environment is not None:
        rows = [s for s in rows if s.get("environment") == environment]
    if status is not None:
        rows = [s for s in rows if s.get("status") == status]
    if q is not None and q.strip() != "":
        qq = q.strip().lower()
        def _m(s):
            return (s.get("name") or "").lower().find(qq) >= 0 or (s.get("base_url") or "").lower().find(qq) >= 0
        rows = [s for s in rows if _m(s)]

    # sort by updated_at desc then created_at desc
    def _k(s):
        return (s.get("updated_at") or "", s.get("created_at") or "")
    rows.sort(key=_k, reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    # choose a server context for audit FK: use first row if exists else any non-deleted else any
    server_ctx = None
    if page:
        server_ctx = page[0].get("id")
    else:
        cand = [s for s in servers if s.get("status") != "deleted"] or servers
        server_ctx = cand[0].get("id") if cand else None

    # record audit event (best-effort)
    if server_ctx is not None:
        audits.append({
            "id": "mcp_aud_" + base64.urlsafe_b64encode(os.urandom(18)).decode("utf-8").rstrip("="),
            "server_id": server_ctx,
            "identity_id": None,
            "session_id": None,
            "event_type": "server.updated",
            "success": True,
            "ip_address": None,
            "user_agent": None,
            "metadata": {"endpoint": "List MCP Servers", "filters": {"environment": environment, "status": status, "q": q, "limit": limit, "cursor": cursor}},
            "created_at": now,
            "updated_at": now
        })
        _save("audit_events.json", audits)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "data": [{
            "id": s.get("id"),
            "name": s.get("name"),
            "base_url": s.get("base_url"),
            "environment": s.get("environment"),
            "status": s.get("status"),
            "last_seen_at": s.get("last_seen_at"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        } for s in page],
        "pagination": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
        "meta": {"latency_ms": latency_ms}
    }

def Create_MCP_Server(name, base_url, environment, **_extra):
    import json, os, datetime, re, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0393000" if __import__("os").path.isdir("./environment_mix/0393000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # validate
    if not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string")
    if not (1 <= len(name) <= 200):
        return _err("VALIDATION_ERROR", "name length must be between 1 and 200")
    if name.strip() == "":
        return _err("VALIDATION_ERROR", "name must not be empty")
    if not isinstance(base_url, str):
        return _err("VALIDATION_ERROR", "base_url must be a string")
    if not (1 <= len(base_url) <= 2048):
        return _err("VALIDATION_ERROR", "base_url length must be between 1 and 2048")
    if base_url.strip() == "":
        return _err("VALIDATION_ERROR", "base_url must not be empty")
    if not isinstance(environment, str):
        return _err("VALIDATION_ERROR", "environment must be a string")
    if environment not in ["local", "dev", "staging", "prod"]:
        return _err("VALIDATION_ERROR", "Invalid environment")

    servers = _load("mcp_servers.json")
    audits = _load("audit_events.json")

    # uniqueness: unique(name, environment)
    if any(s.get("name") == name and s.get("environment") == environment for s in servers):
        return _err("CONFLICT", "A server with this name already exists in the environment", name=name, environment=environment)

    def _b32_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        raw = (datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f") + os.urandom(10).hex()).encode("utf-8")
        h = hashlib.sha256(raw).digest()
        n = 0
        for b in h[:16]:
            n = (n << 8) | b
        chars = []
        for _ in range(26):
            n, r = divmod(n, 32)
            chars.append(alphabet[r])
        return prefix + "".join(reversed(chars))

    new_srv = {
        "id": _b32_id("mcp_srv_"),
        "name": name,
        "base_url": base_url,
        "environment": environment,
        "status": "active",
        "last_seen_at": None,
        "created_at": now,
        "updated_at": now
    }
    servers.append(new_srv)

    audits.append({
        "id": _b32_id("mcp_aud_"),
        "server_id": new_srv["id"],
        "identity_id": None,
        "session_id": None,
        "event_type": "server.created",
        "success": True,
        "ip_address": None,
        "user_agent": None,
        "metadata": {"name": name, "environment": environment, "base_url": base_url},
        "created_at": now,
        "updated_at": now
    })

    _save("mcp_servers.json", servers)
    _save("audit_events.json", audits)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "server": new_srv,
        "meta": {"latency_ms": latency_ms}
    }

