    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _audit_id():
        # mcp_aud_ + base32-ish time/random
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(now_dt.timestamp() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        n = (ts << 80) | rnd
        s = ""
        for _ in range(26):
            s = alphabet[n & 31] + s
            n >>= 5
        return "mcp_aud_" + s

    def _log_event(event_type, success, server_id_val, identity_id=None, session_id=None, metadata=None):
        audits = _load("audit_events.json")
        row = {
            "id": _audit_id(),
            "server_id": server_id_val,
            "identity_id": identity_id,
            "session_id": session_id,
            "event_type": event_type,
            "success": bool(success),
            "ip_address": None,
            "user_agent": None,
            "metadata": metadata if isinstance(metadata, dict) else None,
            "created_at": _iso(now_dt),
            "updated_at": _iso(now_dt),
        }
        audits.append(row)
        _save("audit_events.json", audits)

    # ---- Validate inputs ----
    if not isinstance(server_id, str) or re.match(r"^mcp_srv_[0-9A-HJKMNP-TV-Z]{18,}$", server_id) is None:
        _log_event("server.updated", False, server_id if isinstance(server_id, str) else "mcp_srv_invalid", metadata={"reason": "validation_error", "field": "server_id"})
        return _err("VALIDATION_ERROR", "Invalid server_id.")
    if name is not None:
        if not isinstance(name, str):
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "name"})
            return _err("VALIDATION_ERROR", "Invalid name; must be a string.")
        if len(name) < 1 or len(name) > 200 or name.strip() == "":
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "name"})
            return _err("VALIDATION_ERROR", "Invalid name; must be 1..200 characters and non-empty.")
    if base_url is not None:
        if not isinstance(base_url, str):
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "base_url"})
            return _err("VALIDATION_ERROR", "Invalid base_url; must be a string.")
        if len(base_url) < 1 or len(base_url) > 2048 or base_url.strip() == "":
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "base_url"})
            return _err("VALIDATION_ERROR", "Invalid base_url; must be 1..2048 characters and non-empty.")
    if environment is not None:
        if not isinstance(environment, str) or environment not in ("local", "dev", "staging", "prod"):
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "environment"})
            return _err("VALIDATION_ERROR", "Invalid environment.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status.")

    # ---- Load & locate server ----
    servers = _load("mcp_servers.json")
    srv_idx = None
    for i, s in enumerate(servers):
        if s.get("id") == server_id:
            srv_idx = i
            break
    if srv_idx is None:
        _log_event("server.updated", False, server_id, metadata={"reason": "not_found"})
        return _err("NOT_FOUND", "Server not found.", server_id=server_id)
    srv = servers[srv_idx]

    # ---- Apply updates (enforce constraints and lifecycle) ----
    changed_fields = {}
    old_status = srv.get("status")
    new_status = status if status is not None else old_status

    # Unique(name, environment) constraint when either changes (or when provided explicitly)
    new_name = srv.get("name") if name is None else name
    new_env = srv.get("environment") if environment is None else environment

    # base_url <> '' and name <> '' already validated
    if new_name is not None and new_env is not None:
        for s in servers:
            if s.get("id") != server_id and s.get("name") == new_name and s.get("environment") == new_env:
                _log_event("server.updated", False, server_id, metadata={"reason": "conflict", "constraint": "unique(name, environment)"})
                return _err("CONFLICT", "A server with the same name and environment already exists.", name=new_name, environment=new_env)

    # Lifecycle transitions:
    # IMPORTANT: Accepting "deleted -> active" is required for this datastore's reality (audit defect),
    # treating "deleted" as soft-delete reversible in this tool.
    allowed = {
        "active": {"disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": {"active", "disabled", "deleted"},
    }
    if status is not None:
        if old_status not in allowed:
            _log_event("server.updated", False, server_id, metadata={"reason": "validation_error", "field": "status", "from_status": old_status, "to_status": new_status})
            return _err("VALIDATION_ERROR", "Invalid current server status in datastore.", from_status=old_status)
        if new_status != old_status and new_status not in allowed.get(old_status, set()):
            _log_event("server.updated", False, server_id, metadata={"reason": "invalid_transition", "from_status": old_status, "to_status": new_status})
            return _err(
                "INVALID_TRANSITION",
                "Illegal server status transition under this service's lifecycle rules.",
                from_status=old_status,
                to_status=new_status,
            )

    # Determine if any effective change will happen
    if name is not None and name != srv.get("name"):
        changed_fields["name"] = {"from": srv.get("name"), "to": name}
        srv["name"] = name
    if base_url is not None and base_url != srv.get("base_url"):
        changed_fields["base_url"] = {"from": srv.get("base_url"), "to": base_url}
        srv["base_url"] = base_url
    if environment is not None and environment != srv.get("environment"):
        changed_fields["environment"] = {"from": srv.get("environment"), "to": environment}
        srv["environment"] = environment
    if status is not None and new_status != old_status:
        changed_fields["status"] = {"from": old_status, "to": new_status}
        srv["status"] = new_status

    # If nothing would change, do not report success without effect
    if not changed_fields:
        _log_event("server.updated", False, server_id, metadata={"reason": "no_effect"})
        return _err("CONFLICT", "No changes to apply (request is idempotent with current state).")

    # Update timestamps
    srv["updated_at"] = _iso(now_dt)

    # If disabling server => revoke all active sessions for that server
    revoked_count = 0
    if old_status != "disabled" and srv.get("status") == "disabled":
        sessions = _load("auth_sessions.json")
        for sess in sessions:
            if sess.get("server_id") == server_id and sess.get("status") == "active":
                sess["status"] = "revoked"
                sess["updated_at"] = _iso(now_dt)
                # keep any last_error as-is; add a minimal marker if none
                if not sess.get("last_error"):
                    sess["last_error"] = "revoked_by_server_disable"
                revoked_count += 1
                _log_event("auth.session.revoked", True, server_id, identity_id=sess.get("identity_id"), session_id=sess.get("id"), metadata={"reason": "server_disabled"})
        _save("auth_sessions.json", sessions)
        _log_event("server.disabled", True, server_id, metadata={"revoked_active_sessions": revoked_count})

    # If deleted => just mark; no cascading deletions (soft-delete)
    if old_status != "deleted" and srv.get("status") == "deleted":
        _log_event("server.deleted", True, server_id, metadata={"soft_delete": True})

    # Persist server update
    servers[srv_idx] = srv
    _save("mcp_servers.json", servers)

    _log_event(
        "server.updated",
        True,
        server_id,
        metadata={
            "changed": list(changed_fields.keys()),
            "status_transition": {"from": old_status, "to": srv.get("status")} if status is not None else None,
            "revoked_active_sessions": revoked_count if srv.get("status") == "disabled" else None,
        },
    )

    latency_ms = int((time.time() - t0) * 1000)
    # Touch last_seen_at on successful use/update
    try:
        servers2 = _load("mcp_servers.json")
        for s in servers2:
            if s.get("id") == server_id:
                s["last_seen_at"] = _iso(now_dt)
                s["updated_at"] = _iso(now_dt)
                break
        _save("mcp_servers.json", servers2)
    except Exception:
        pass

    return {"server": srv, "latency_ms": latency_ms}

def List_Auth_Sessions(server_id=None, identity_id=None, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0393000" if __import__("os").path.isdir("./environment_mix/0393000") else "/app/database")
    def _load(n):
