            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _audit_id():
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts = int(now.timestamp() * 1000)
        rnd = int.from_bytes(os.urandom(10), "big")
        n = (ts << 80) | rnd
        s = ""
        for _ in range(26):
            s = alphabet[n & 31] + s
            n >>= 5
        return "mcp_aud_" + s

    def _log_event(success, metadata=None, resolved_server_id=None, resolved_identity_id=None):
        audits = _load("audit_events.json")
        # Use a server_id that exists if possible to satisfy FK restrict; otherwise omit by choosing any existing server.
        sid = resolved_server_id
        if not sid:
            servers = _load("mcp_servers.json")
            sid = servers[0]["id"] if servers else "mcp_srv_unknown"
        row = {
            "id": _audit_id(),
            "server_id": sid,
            "identity_id": resolved_identity_id,
            "session_id": None,
            "event_type": "auth.signin.started",  # closest available enum for "session list/read" to ensure audit trail exists
            "success": bool(success),
            "ip_address": None,
            "user_agent": None,
            "metadata": metadata if isinstance(metadata, dict) else None,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        audits.append(row)
        _save("audit_events.json", audits)

    # ---- Validate inputs (relax to accept actual datastore ids) ----
    if server_id is not None:
        if not isinstance(server_id, str) or re.match(r"^mcp_srv_[0-9A-HJKMNP-TV-Z]{18,}$", server_id) is None:
            _log_event(False, {"reason": "validation_error", "field": "server_id"})
            return _err("VALIDATION_ERROR", "Invalid server_id.")
    if identity_id is not None:
        # Tool schema has a too-strict pattern (^mcp_id_), but datastore uses mcp_idn_...; accept both.
        if not isinstance(identity_id, str) or re.match(r"^mcp_id(n)?_[0-9A-HJKMNP-TV-Z]{18,}$", identity_id) is None:
            _log_event(False, {"reason": "validation_error", "field": "identity_id"}, resolved_server_id=server_id)
            return _err("VALIDATION_ERROR", "Invalid identity_id.")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "expired", "revoked", "error"):
            _log_event(False, {"reason": "validation_error", "field": "status"}, resolved_server_id=server_id, resolved_identity_id=identity_id)
            return _err("VALIDATION_ERROR", "Invalid status.")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log_event(False, {"reason": "validation_error", "field": "limit"}, resolved_server_id=server_id, resolved_identity_id=identity_id)
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..100.")
    if cursor is not None and not isinstance(cursor, str):
        _log_event(False, {"reason": "validation_error", "field": "cursor"}, resolved_server_id=server_id, resolved_identity_id=identity_id)
        return _err("VALIDATION_ERROR", "Invalid cursor.")

    # ---- Load data ----
    servers = _load("mcp_servers.json")
    identities = _load("auth_identities.json")
    sessions = _load("auth_sessions.json")

    # Validate references only if provided; do not error if filter yields no rows.
    if server_id is not None:
        if not any(s.get("id") == server_id for s in servers):
            _log_event(True, {"note": "server_id not found; returning empty"}, resolved_server_id=servers[0]["id"] if servers else None, resolved_identity_id=identity_id)
            return {
                "sessions": [],
                "total": 0,
                "limit": limit,
                "has_more": False,
                "next_cursor": None,
                "latency_ms": int((time.time() - t0) * 1000),
            }
    if identity_id is not None:
        if not any(i.get("id") == identity_id for i in identities):
            # It's a filter; if not found, return empty rather than error.
            _log_event(True, {"note": "identity_id not found; returning empty"}, resolved_server_id=server_id or (servers[0]["id"] if servers else None), resolved_identity_id=None)
            return {
                "sessions": [],
                "total": 0,
                "limit": limit,
                "has_more": False,
                "next_cursor": None,
                "latency_ms": int((time.time() - t0) * 1000),
            }

    # ---- On read: mark expired if expires_at in past ----
    mutated = False
    for sess in sessions:
        exp = _parse_dt(sess.get("expires_at"))
        if exp is not None and exp <= now and sess.get("status") == "active":
            sess["status"] = "expired"
            sess["updated_at"] = _iso(now)
            sess["last_error"] = "session_read: expires_at in past; marked expired"
            mutated = True
    if mutated:
        _save("auth_sessions.json", sessions)

    # ---- Filter ----
    filtered = []
    for sess in sessions:
        if server_id is not None and sess.get("server_id") != server_id:
            continue
        if identity_id is not None and sess.get("identity_id") != identity_id:
            continue
        if status is not None and sess.get("status") != status:
            continue
        filtered.append(sess)

    # Stable sort: updated_at desc then id desc
    def _sort_key(s):
        dt = _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, s.get("id") or "")
    filtered.sort(key=_sort_key, reverse=True)

    # ---- Pagination: cursor is treated as "start after this id" in the sorted list ----
    start = 0
    if cursor:
        for i, s in enumerate(filtered):
            if s.get("id") == cursor:
                start = i + 1
                break
        else:
            start = 0

    page = filtered[start:start + limit]
    next_cursor = page[-1].get("id") if len(page) == limit and (start + limit) < len(filtered) else None

    # Never return raw token ciphertexts
    def _public_session(s):
        return {
            "id": s.get("id"),
            "server_id": s.get("server_id"),
            "identity_id": s.get("identity_id"),
            "expires_at": s.get("expires_at"),
            "status": s.get("status"),
            "last_error": s.get("last_error"),
            "created_at": s.get("created_at"),
            "updated_at": s.get("updated_at"),
        }

    # Audit call (read)
    resolved_sid = server_id or (page[0].get("server_id") if page else (servers[0]["id"] if servers else None))
    _log_event(True, {"action": "list_sessions", "returned": len(page), "total": len(filtered)}, resolved_server_id=resolved_sid, resolved_identity_id=identity_id)

    # Touch last_seen_at for server if a specific server_id was used and exists
    if server_id is not None:
        try:
            for s in servers:
                if s.get("id") == server_id:
                    s["last_seen_at"] = _iso(now)
                    s["updated_at"] = _iso(now)
                    _save("mcp_servers.json", servers)
                    break
        except Exception:
            pass

    return {
        "sessions": [_public_session(s) for s in page],
        "total": len(filtered),
        "limit": limit,
        "has_more": next_cursor is not None,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000),
    }

