            "created_at": _iso(now),
            "updated_at": _iso(now),
        })
        _save("audit_events.json", audit)
        return _err("NOT_FOUND", "Session not found.")

    server_id = sess.get("server_id")
    identity_id = sess.get("identity_id")
    srv = server_by_id.get(server_id)
    ident = ident_by_id.get(identity_id)

    if srv is None:
        return _err("NOT_FOUND", "Owning server not found for session.")
    if ident is None:
        return _err("NOT_FOUND", "Owning identity not found for session.")

    # On read/refresh attempts, expire if past
    exp = _parse_dt(sess.get("expires_at"))
    if exp is not None and exp <= now and sess.get("status") == "active":
        sess["status"] = "expired"
        sess["updated_at"] = _iso(now)

    # If refresh requested, enforce server/identity eligibility
    if refresh:
        if srv.get("status") in ("disabled", "deleted"):
            evt_id = "mcp_aud_" + hashlib.sha256((str(now.timestamp()) + "refresh denied").encode("utf-8")).hexdigest()[:22]
            audit.append({
                "id": evt_id,
                "server_id": server_id,
                "identity_id": identity_id,
                "session_id": session_id,
                "event_type": "auth.signin.failed",
                "success": False,
                "ip_address": None,
                "user_agent": None,
                "metadata": {"endpoint": "Update Auth Session", "refresh": True, "error": "server_disabled_or_deleted"},
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("audit_events.json", audit)
            return _err("UNAUTHORIZED", "Server is disabled or deleted; cannot refresh session.")
        if ident.get("status") in ("revoked", "deleted"):
            evt_id = "mcp_aud_" + hashlib.sha256((str(now.timestamp()) + "refresh denied ident").encode("utf-8")).hexdigest()[:22]
            audit.append({
                "id": evt_id,
                "server_id": server_id,
                "identity_id": identity_id,
                "session_id": session_id,
                "event_type": "auth.signin.failed",
                "success": False,
                "ip_address": None,
                "user_agent": None,
                "metadata": {"endpoint": "Update Auth Session", "refresh": True, "error": "identity_revoked_or_deleted"},
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("audit_events.json", audit)
            return _err("UNAUTHORIZED", "Identity is revoked or deleted; cannot refresh session.")

        # Attempt refresh: offline implementation simulates a successful refresh by extending expiry if expiry exists.
        # If expires_at is null (static key), simply mark active and clear error.
        if exp is None:
            new_exp = None
        else:
            new_exp = now + datetime.timedelta(hours=1)
        desired_status = "active"
        status = desired_status  # drive transition through status logic below
        if last_error is None:
            last_error = None
        sess["expires_at"] = _iso(new_exp) if new_exp is not None else None

    # Apply status transition if requested
    if status is not None:
        cur = sess.get("status")
        allowed = {
            "active": {"expired", "revoked", "error"},
            "error": {"active", "revoked"},
            "expired": {"active", "revoked"},
            "revoked": set(),
        }
        if cur not in allowed or status not in ("active", "expired", "revoked", "error"):
            return _err("VALIDATION_ERROR", "Invalid current or target status.")
        if status != cur and status not in allowed.get(cur, set()):
            # audit
            evt_id = "mcp_aud_" + hashlib.sha256((str(now.timestamp()) + "invalid transition").encode("utf-8")).hexdigest()[:22]
            audit.append({
                "id": evt_id,
                "server_id": server_id,
                "identity_id": identity_id,
                "session_id": session_id,
                "event_type": "auth.signin.failed",
                "success": False,
                "ip_address": None,
                "user_agent": None,
                "metadata": {"endpoint": "Update Auth Session", "error": "invalid_transition", "from": cur, "to": status},
                "created_at": _iso(now),
                "updated_at": _iso(now),
            })
            _save("audit_events.json", audit)
            return _err("INVALID_TRANSITION", f"Illegal transition {cur} → {status}.")

        # If setting error, last_error may be provided; if not, keep existing.
        if status == "error":
            if last_error is not None:
                sess["last_error"] = last_error
            elif sess.get("last_error") is None:
                sess["last_error"] = "Unknown error"
        elif status == "active":
            # Clear error on successful reactivation/refresh unless caller explicitly provided a last_error
            if last_error is not None:
                sess["last_error"] = last_error
            else:
                sess["last_error"] = None
        elif status in ("revoked", "expired"):
            if last_error is not None:
                sess["last_error"] = last_error

        # Enforce one active session per (server_id, identity_id)
        if status == "active":
            # server/identity must be eligible
            if srv.get("status") in ("disabled", "deleted"):
                return _err("UNAUTHORIZED", "Server is disabled or deleted; cannot activate session.")
            if ident.get("status") in ("revoked", "deleted"):
                return _err("UNAUTHORIZED", "Identity is revoked or deleted; cannot activate session.")

            for other in sessions:
                if not isinstance(other, dict):
                    continue
                if other.get("id") == session_id:
                    continue
                if other.get("server_id") == server_id and other.get("identity_id") == identity_id and other.get("status") == "active":
                    # Must revoke or expire previous active session as part of operation
                    other["status"] = "revoked"
                    other["updated_at"] = _iso(now)
                    # audit event for revoke
                    evt_id2 = "mcp_aud_" + hashlib.sha256((str(now.timestamp()) + "auto revoke" + str(other.get("id"))).encode("utf-8")).hexdigest()[:22]
                    audit.append({
                        "id": evt_id2,
                        "server_id": server_id,
                        "identity_id": identity_id,
                        "session_id": other.get("id"),
                        "event_type": "auth.session.revoked",
                        "success": True,
                        "ip_address": None,
                        "user_agent": None,
                        "metadata": {"reason": "superseded_by_activation", "superseding_session_id": session_id},
                        "created_at": _iso(now),
                        "updated_at": _iso(now),
                    })

        sess["status"] = status
        sess["updated_at"] = _iso(now)

    # Update last_error alone (without status change)
    if status is None and last_error is not None:
        sess["last_error"] = last_error
        sess["updated_at"] = _iso(now)

    # If disabling server rule: not triggered here unless server already disabled; but if server disabled, all active sessions should be revoked.
    # We'll enforce consistency: if server is disabled and session is active, revoke it and refuse activation.
    if srv.get("status") == "disabled" and sess.get("status") == "active":
        sess["status"] = "revoked"
        sess["updated_at"] = _iso(now)

    # Persist changes
    _save("auth_sessions.json", sessions)

    # Audit success
    latency_ms = int((time.time() - t0) * 1000)
    evt_type = "auth.session.refreshed" if refresh else ("auth.session.revoked" if sess.get("status") == "revoked" else "auth.signin.succeeded")
    evt_id = "mcp_aud_" + hashlib.sha256((str(now.timestamp()) + "Update Auth Session" + str(latency_ms)).encode("utf-8")).hexdigest()[:22]
    audit.append({
        "id": evt_id,
        "server_id": server_id,
        "identity_id": identity_id,
        "session_id": session_id,
        "event_type": evt_type,
        "success": True,
        "ip_address": None,
        "user_agent": None,
        "metadata": {
            "endpoint": "Update Auth Session",
            "refresh": bool(refresh),
            "new_status": sess.get("status"),
            "expires_at_present": sess.get("expires_at") is not None,
            "latency_ms": latency_ms,
        },
        "created_at": _iso(now),
        "updated_at": _iso(now),
    })
    _save("audit_events.json", audit)

    # Update server last_seen_at
    if isinstance(srv, dict) and srv.get("status") != "deleted":
        srv["last_seen_at"] = _iso(now)
        srv["updated_at"] = _iso(now)
        _save("mcp_servers.json", servers)

    # Return redacted session metadata
    return {
        "data": {
            "id": sess.get("id"),
            "server_id": sess.get("server_id"),
            "identity_id": sess.get("identity_id"),
            "expires_at": sess.get("expires_at"),
            "status": sess.get("status"),
            "last_error": sess.get("last_error"),
            "created_at": sess.get("created_at"),
            "updated_at": sess.get("updated_at"),
        }
    }
